import { initNews } from './observatorio-news.mjs';
const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url = s => { try { const u = new URL(s); return u.protocol === 'https:' ? u.href : '#'; } catch { return '#'; } };
const link = (href, text) => `<a href="${esc(url(href))}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`;
const date = s => new Date(s).toLocaleString('es-CL', { dateStyle:'medium', timeStyle:'short' });
const KEY = 'atlas-observatorio-research-v1';
let research = { title:'Eventos naturales y territorio', events:[], facts:'', hypotheses:'', questions:'' };
try { const saved = JSON.parse(localStorage.getItem(KEY)); if (saved && Array.isArray(saved.events) && typeof saved.title === 'string') research = { ...research, ...saved, events:saved.events.filter(e => e && typeof e.id === 'string' && e.title && e.date && e.url).slice(0,100) }; } catch {}
let events = [], sources = [], filter = 'all', selected, fetchedAt, map, markers;
function save() { try { localStorage.setItem(KEY, JSON.stringify(research)); $('save-status').textContent = 'Guardado en este navegador · ' + new Date().toLocaleTimeString('es-CL') + '. Sin sincronización entre dispositivos.'; } catch { $('save-status').textContent = 'No se pudo guardar en el navegador. Exporta tu investigación para conservarla.'; } }
function view(name) { document.querySelectorAll('.view').forEach(el => el.hidden = el.id !== name); document.querySelectorAll('[data-view]').forEach(b => { b.classList.toggle('active', b.dataset.view === name); b.setAttribute('aria-pressed', b.dataset.view === name); }); if (name === 'panorama') setTimeout(() => map?.invalidateSize(),0); if (name === 'investigacion') renderResearch(); if(!/(?:access_token|refresh_token|error_description|code)=/.test(location.hash + location.search)) location.hash = name; }
document.querySelectorAll('[data-view]').forEach(b => b.onclick = () => view(b.dataset.view));
window.addEventListener('hashchange', () => { const name = location.hash.slice(1); if (['feed','panorama','investigacion','fuentes'].includes(name)) view(name); });
if (window.L) { map = L.map('map', { worldCopyJump:true, minZoom:2 }).setView([-8,-48],3); L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom:18, attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors' }).addTo(map).on('tileerror', () => { $('status').textContent = 'Algunas teselas del mapa no cargaron. Las señales siguen disponibles en la lista.'; }); markers = L.layerGroup().addTo(map); L.control.scale({imperial:false}).addTo(map); } else $('map').innerHTML = '<p class="empty">No se pudo cargar el mapa. Puedes explorar las señales en la lista y reintentar recargando.</p>';
$('chile').onclick = () => map?.setView([-33.45,-70.66],5);
$('world').onclick = () => map?.setView([8,-35],2);
function filtered() { const q = $('search').value.trim().toLocaleLowerCase(); const cutoff = Date.now()-Number($('period').value)*86400000; return events.filter(e => (filter === 'all' || e.provider === filter) && Date.parse(e.date) >= cutoff && `${e.title} ${e.source} ${e.category}`.toLocaleLowerCase().includes(q)); }
function eventCard(e, cls = 'event') { return `<button class="${cls}" data-event="${esc(e.id)}"><span class="tag">${esc(e.source)} · ${esc(e.category)}</span><strong>${esc(e.title)}</strong><small>${esc(date(e.date))}</small></button>`; }
function bindEvents(root, fn = showDetail) { root.querySelectorAll('[data-event]').forEach(b => b.onclick = () => { const e = research.events.find(e => e.id === b.dataset.event) || events.find(e => e.id === b.dataset.event); if (e) fn(e); }); }
function render() {
  const rows = filtered(); $('count').textContent = `${rows.length} señales en el mapa`; $('result-count').textContent = rows.length;
  $('events').innerHTML = rows.length ? rows.map(e => eventCard(e)).join('') : '<div class="empty">Sin señales para estos filtros.<br>Prueba otro periodo o búsqueda.</div>'; bindEvents($('events'));
  markers?.clearLayers(); for (const e of rows) { if (!map) break; const marker = L.circleMarker([e.coordinates[1],e.coordinates[0]], { radius:6, color:'#ffffff', weight:1.5, fillColor:e.provider === 'usgs' ? '#c66e43':'#087c70', fillOpacity:.82 }).addTo(markers); const tip = document.createElement('span'); tip.textContent=e.title; marker.bindTooltip(tip).on('click', () => showDetail(e)); }
  const days = Array.from({length:7}, (_,i) => { const d = new Date(); d.setUTCDate(d.getUTCDate()-6+i); const key=d.toISOString().slice(0,10); return { label:d.toLocaleDateString('es-CL',{day:'numeric',month:'short',timeZone:'UTC'}), count:rows.filter(e => e.date.startsWith(key)).length }; }); const max=Math.max(1,...days.map(d => d.count)); $('chart').innerHTML=days.map(d => `<div class="bar" style="height:${Math.max(2,d.count/max*75)}px" title="${esc(d.label)}: ${d.count}"><b>${d.count}</b><span>${esc(d.label)}</span></div>`).join('');
}
function evidence(e, saved = false) { return `<span class="badge">${esc(e.source)}</span><h2>${esc(e.title)}</h2><p>${esc(e.detail)}</p><dl class="metadata"><dt>Registro</dt><dd>${esc(date(e.date))}</dd><dt>Consulta</dt><dd>${esc(date(e.capturedAt || fetchedAt || new Date()))}</dd><dt>Ubicación</dt><dd>${esc(e.coordinates?.[1])}, ${esc(e.coordinates?.[0])}</dd><dt>Corroboración</dt><dd>No evaluada. Registro atribuido a su proveedor.</dd></dl><p>${link(e.url,'Abrir registro original')}</p>${e.links?.length ? '<p>Referencias del proveedor: '+e.links.map(l => link(l.url,l.name)).join(' · ')+'</p>':''}<div class="actions">${saved ? '<button id="remove-evidence">Quitar de investigación</button>' : '<button id="add-evidence" class="primary">＋ Guardar en investigación</button>'}</div>`; }
function showDetail(e) { selected=e; const saved=research.events.some(x => x.id === e.id); $('detail-content').innerHTML=evidence(e,saved); $('detail').showModal(); const add=$('detail-content').querySelector('#add-evidence'); if(add) add.onclick=() => { if (research.events.length>=100) { add.textContent='Límite de 100 evidencias. Exporta o quita alguna.'; return; } research.events.push({...e,capturedAt:fetchedAt}); save(); $('detail').close(); view('investigacion'); }; const remove=$('detail-content').querySelector('#remove-evidence'); if(remove) remove.onclick=() => { research.events=research.events.filter(x=>x.id!==e.id); save(); $('detail').close(); renderResearch(); }; }
$('close-detail').onclick=()=> $('detail').close();
function renderResearch() {
  $('research-title').value=research.title; document.querySelectorAll('[data-note]').forEach(el=>el.value=research[el.dataset.note]||'');
  $('graph').innerHTML=research.events.length ? `<div class="graph-center">${esc(research.title)}</div><div class="graph-nodes">${research.events.map(e=>`<button class="graph-node" data-event="${esc(e.id)}">${esc(e.title)}<small>${esc(e.source)}</small></button>`).join('')}</div>` : '<div class="empty">Tu investigación empieza con una fuente.<br>Abre una señal en el panorama y guárdala aquí.</div>';
  bindEvents($('graph'), e=>{ selected=e; renderInspector(e); });
  $('timeline').innerHTML=[...research.events].sort((a,b)=>a.date.localeCompare(b.date)).map(e=>eventCard(e)).join('') || '<p class="muted">Todavía no hay evidencias guardadas.</p>'; bindEvents($('timeline'),e=>{ selected=e; renderInspector(e); });
  const current=research.events.find(e=>e.id===selected?.id)||research.events[0]; if(current) renderInspector(current); else $('evidence').innerHTML='<div class="empty">Selecciona una señal del panorama para ver su fuente y contexto.</div>';
}
function renderInspector(e) { $('evidence').innerHTML=evidence(e,true); $('evidence').querySelector('#remove-evidence').onclick=()=> { research.events=research.events.filter(x=>x.id!==e.id); save(); renderResearch(); }; }
$('research-title').oninput=e=>{ research.title=e.target.value; save(); const center=document.querySelector('.graph-center'); if(center) center.textContent=research.title; };
document.querySelectorAll('[data-note]').forEach(el=>el.oninput=()=>{ research[el.dataset.note]=el.value; save(); });
$('export').onclick=()=>{ const blob=new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),...research},null,2)],{type:'application/json'}); const href=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=href; a.download='investigacion-osint.json'; a.click(); setTimeout(()=>URL.revokeObjectURL(href),1000); };
function renderSources() { $('coverage').innerHTML=sources.map(s=>`<div class="coverage-row"><strong>${esc(s.name)}</strong><span class="${s.status==='ok'?'ok':'error'}">${s.status==='ok'?s.count+' registros':'Sin conexión'}</span></div>`).join(''); $('source-list').innerHTML=sources.map(s=>`<section class="panel source-card"><span class="source-status ${s.status==='ok'?'ok':'error'}">${s.status==='ok'?'● Conectada':'● No disponible'}</span><h2>${esc(s.name)}</h2><p>${esc(s.scope)}</p><p class="muted">Consulta: ${esc(date(s.checkedAt))} · ${s.count} registros recibidos${s.error?' · '+esc(s.error):''}</p>${link(s.docs,'Documentación')}${link(s.url,'Datos originales')}</section>`).join(''); }
async function refresh() { $('refresh').disabled=true; $('status').textContent='Consultando USGS y NASA EONET…'; try { const res=await fetch('/.netlify/functions/observatory',{signal:AbortSignal.timeout(20000)}); if(!res.ok) throw Error(); const data=await res.json(); if(!Array.isArray(data.events)||!Array.isArray(data.sources)) throw Error(); events=data.events; sources=data.sources; fetchedAt=data.fetchedAt; render(); renderSources(); const failed=sources.filter(s=>s.status!=='ok'); $('status').textContent=`Consulta: ${date(fetchedAt)} · ${failed.length ? 'Cobertura parcial: '+failed.map(s=>s.name).join(', ')+' no disponible.' : '2 fuentes conectadas.'} Los conectores se actualizan como máximo cada 5 minutos.`; } catch { $('status').textContent='No se pudo actualizar. '+(events.length?'Se conserva la consulta anterior; revisa su fecha.':'No hay datos disponibles. Usa Actualizar fuentes para reintentar.'); if(!events.length) { render(); $('coverage').textContent='Conexión no disponible'; $('source-list').textContent='No se pudo obtener el estado de las fuentes. Reintenta con Actualizar fuentes.'; } } finally { $('refresh').disabled=false; } }
$('search').oninput=()=>{ if($('panorama').hidden)view('panorama');render(); }; $('period').onchange=render;
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});render()});
const news = initNews({ view, esc, date });
$('refresh').onclick=()=>Promise.allSettled([refresh(),news.refresh()]); view(['feed','panorama','investigacion','fuentes'].includes(location.hash.slice(1))?location.hash.slice(1):'feed'); refresh();
